#include <iostream>
#include <algorithm>
#include <cstdlib>
#include <bitset>
using namespace std;
int mn(int A[], int n)
{
    if (n == 1) return A[0];
    int m = mn(A, n - 1);
    cout << n << ":" << m << " ";
    return A[n - 1] < m ? A[n - 1] : m;
}
int main()
{
    int A[] = {4, 2, 7, 1, 5};
    cout << mn(A, 5) << endl;
    return 0;
}

