#include <iostream>
#include <algorithm>
#include <cstdlib>
#include <bitset>
using namespace std;
int main()
{
    int A[3] = {3, 5, 2}, B[3] = {4, 1, 6};
    int best = 1000000, ways = 0;
    for (int mask = 0; mask < 8; mask++) {
        int t1 = 0, t2 = 0;
        for (int i = 0; i < 3; i++)
            if ((mask >> i) & 1) t1 += A[i]; else t2 += B[i];
        int cost = t1 > t2 ? t1 : t2;
        if (cost < best) { best = cost; ways = 1; }
        else if (cost == best) ways++;
    }
    cout << best << " " << ways << endl;
    return 0;
}

